//! # pathland-render-html
//!
//! A Pathland renderer that maps opcode frames onto **declarative HTML**
//! elements. Like every Pathland renderer it is a pure function of the opcode
//! stream: it retains only its own decoded output tree (a cache), never
//! application state, and emits `WHAT` the UI is — never layout rects. Native
//! browser layout does the positioning.
//!
//! This is the "server-side render" / remote-projection target (Goal #15): the
//! same opcode stream that drives a native backend drives this HTML document.
//!
//! Frames are **self-contained**: `apply(opcodes, strings)` resolves `SET_TEXT`
//! by a *relative* offset into the frame's own string section (no mirrored
//! arena), and every rendered element carries a stable `data-pathland-id` so a
//! client can hydrate it and apply later deltas in place.

use std::collections::BTreeMap;

use pathland_core::{
    Opcode, border_edges, category, component_type, property_id, style, tokens::TokenValue, tree,
    value_type,
};

mod capi;
mod css;
mod debug;
pub mod role_spec;
pub mod token_spec;

/// A decoded node in the retained description.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Node {
    /// Protocol component type id (see `pathland_core::component_type`).
    pub component: u16,
    /// Text content set via `STYLE::SET_TEXT`, if any.
    pub text: Option<String>,
    /// Constraint/style properties (`propertyId → value`).
    pub properties: BTreeMap<u16, u32>,
    /// `STRING`-typed properties resolved at apply time (`propertyId → text`).
    pub strings: BTreeMap<u16, String>,
    /// `DESIGN_TOKEN`-typed properties (`propertyId → token path`).
    pub token_refs: BTreeMap<u16, String>,
    /// Date value from `STYLE::SET_DATE`: (days since epoch, millis of day).
    pub date: Option<(i32, u32)>,
    /// Child node ids in insertion order.
    pub children: Vec<u32>,
}

impl Node {
    fn new(component: u16) -> Self {
        Self {
            component,
            text: None,
            properties: BTreeMap::new(),
            strings: BTreeMap::new(),
            token_refs: BTreeMap::new(),
            date: None,
            children: Vec::new(),
        }
    }

    /// The `SELECTED` checked state, decoded from its `U8` wire value.
    fn checked(&self) -> bool {
        self.properties
            .get(&property_id::SELECTED)
            .copied()
            .unwrap_or(0)
            != 0
    }

    /// The decoded `ROLE` semantic code (0 = none when absent), from its `F32`
    /// wire value.
    fn role_code(&self) -> u8 {
        self.properties
            .get(&property_id::ROLE)
            .map(|b| f32::from_bits(*b) as u8)
            .unwrap_or(0)
    }

    /// The decoded `TEXT_STYLE` typography code (None when absent), from its
    /// `F32` wire value.
    fn text_style_code(&self) -> Option<u8> {
        self.properties
            .get(&property_id::TEXT_STYLE)
            .map(|b| f32::from_bits(*b) as u8)
    }

    /// An `F32` property value, or a default when absent.
    fn f32_property(&self, prop: u16, default: f32) -> f32 {
        self.properties
            .get(&prop)
            .copied()
            .map(f32::from_bits)
            .unwrap_or(default)
    }

    /// `CONTENT_MARGINS` (F32), if present.
    fn content_margins(&self) -> Option<f32> {
        self.properties
            .get(&property_id::CONTENT_MARGINS)
            .map(|bits| f32::from_bits(*bits))
    }

    /// A raw `U32` property value (no f32 reinterpretation), or a default.
    fn u32_property(&self, prop: u16, default: u32) -> u32 {
        self.properties.get(&prop).copied().unwrap_or(default)
    }

    /// If the property carries a `DESIGN_TOKEN` reference, its CSS expression
    /// (`var(--pl-…)` or `calc(var(--pl-space-base) * N)` for the generative
    /// `space.<N>` family). Resolved at render time — the browser resolves the
    /// variable against the token rules in the document head.
    fn token_ref(&self, prop: u16) -> Option<String> {
        self.token_refs.get(&prop).map(|path| resolve_token_ref(path))
    }

    /// Inline CSS for the node. Literal colors and string font-family, plus all
    /// **arbitrary-number (dp/point)** styling — spacing, padding, size, offset,
    /// rotation, scale, filters, opacity, border-radius, z-index — which render
    /// inline because Tailwind can only statically safelist finite enum classes
    /// (dp values are unbounded). 1 dp = 1 CSS px (a renderer interpretation).
    fn style_css(&self) -> String {
        let mut css = String::new();
        let f32p = |prop: u16| self.properties.get(&prop).map(|b| f32::from_bits(*b));
        let px = |v: f32| format!("{v}px");

        // Colors + font family.
        if let Some(v) = self.token_ref(property_id::COLOR) {
            css.push_str(&format!("color:{v};"));
        } else if let Some(bits) = self.properties.get(&property_id::COLOR) {
            css.push_str(&format!("color:{};", rgba(*bits)));
        }
        if let Some(v) = self.token_ref(property_id::BACKGROUND_COLOR) {
            css.push_str(&format!("background-color:{v};"));
        } else if let Some(bits) = self.properties.get(&property_id::BACKGROUND_COLOR) {
            css.push_str(&format!("background-color:{};", rgba(*bits)));
        }
        if let Some(family) = self.strings.get(&property_id::FONT_FAMILY) {
            css.push_str(&format!("font-family:'{}';", family.replace('\'', "\\'")));
        }

        // Layout / distance (dp → px).
        if let Some(v) = self.token_ref(property_id::SPACING) {
            css.push_str(&format!("gap:{v};"));
        } else if let Some(v) = f32p(property_id::SPACING) {
            if v > 0.0 {
                css.push_str(&format!("gap:{};", px(v)));
            }
        }
        if let Some(v) = self.token_ref(property_id::CONTENT_MARGINS) {
            css.push_str(&format!("padding:{v};"));
        } else if let Some(m) = self.content_margins() {
            if m > 0.0 {
                css.push_str(&format!("padding:{};", px(m)));
            }
        }
        if let Some(v) = self.token_ref(property_id::PADDING) {
            css.push_str(&format!("padding:{v};"));
        } else if let Some(v) = f32p(property_id::PADDING) {
            if v > 0.0 {
                css.push_str(&format!("padding:{};", px(v)));
            }
        }
        for (prop, side) in [
            (property_id::PADDING_TOP, "padding-top"),
            (property_id::PADDING_RIGHT, "padding-right"),
            (property_id::PADDING_BOTTOM, "padding-bottom"),
            (property_id::PADDING_LEFT, "padding-left"),
        ] {
            if let Some(v) = self.token_ref(prop) {
                css.push_str(&format!("{side}:{v};"));
            } else if let Some(v) = f32p(prop) {
                if v > 0.0 {
                    css.push_str(&format!("{side}:{};", px(v)));
                }
            }
        }
        // WIDTH/HEIGHT: fixed values inline as px; FILL (-1) → `100%` (expand to
        // the available space in a flex parent — SwiftUI `maxWidth/maxHeight:
        // .infinity`). HUG_CONTENT (-2) is left to the intrinsic size.
        if let Some(v) = self.token_ref(property_id::WIDTH) {
            css.push_str(&format!("width:{v};"));
        } else if let Some(v) = f32p(property_id::WIDTH) {
            if v != pathland_core::size::HUG_CONTENT {
                css.push_str(&format!("width:{};", size_css(v)));
            }
        }
        if let Some(v) = self.token_ref(property_id::HEIGHT) {
            css.push_str(&format!("height:{v};"));
        } else if let Some(v) = f32p(property_id::HEIGHT) {
            if v != pathland_core::size::HUG_CONTENT {
                css.push_str(&format!("height:{};", size_css(v)));
            }
        }
        if let (Some(x), Some(y)) = (f32p(property_id::OFFSET_X), f32p(property_id::OFFSET_Y)) {
            if x != 0.0 || y != 0.0 {
                css.push_str(&format!("transform:translate({}px, {}px);", x, y));
            }
        } else {
            if let Some(v) = f32p(property_id::POSITION_X) {
                if v != 0.0 {
                    css.push_str(&format!("left:{};", px(v)));
                }
            }
            if let Some(v) = f32p(property_id::POSITION_Y) {
                if v != 0.0 {
                    css.push_str(&format!("top:{};", px(v)));
                }
            }
        }

        // Typography (arbitrary size/weight inline).
        if let Some(v) = self.token_ref(property_id::FONT_SIZE) {
            css.push_str(&format!("font-size:{v};"));
        } else if let Some(v) = f32p(property_id::FONT_SIZE) {
            if v > 0.0 {
                css.push_str(&format!("font-size:{};", px(v)));
            }
        }
        if let Some(v) = self.token_ref(property_id::FONT_WEIGHT) {
            css.push_str(&format!("font-weight:{v};"));
        } else if let Some(v) = f32p(property_id::FONT_WEIGHT) {
            if v > 0.0 {
                css.push_str(&format!("font-weight:{v};"));
            }
        }
        if let Some(v) = self.token_ref(property_id::BORDER_RADIUS) {
            css.push_str(&format!("border-radius:{v};"));
        } else if let Some(v) = f32p(property_id::BORDER_RADIUS) {
            if v != 0.0 {
                css.push_str(&format!("border-radius:{};", px(v)));
            }
        }

        // Effects (filters, rotation, scale, shadow, opacity, z-index) inline.
        let mut filters: Vec<String> = Vec::new();
        if let Some(v) = f32p(property_id::BLUR_RADIUS) {
            filters.push(format!("blur({}px)", v));
        }
        if let Some(v) = f32p(property_id::SATURATION) {
            filters.push(format!("saturate({v})"));
        }
        if let Some(v) = f32p(property_id::CONTRAST) {
            filters.push(format!("contrast({v})"));
        }
        if let Some(v) = f32p(property_id::BRIGHTNESS) {
            filters.push(format!("brightness({v})"));
        }
        if let Some(v) = f32p(property_id::GRAYSCALE) {
            filters.push(format!("grayscale({v})"));
        }
        if let Some(v) = f32p(property_id::HUE_ROTATION) {
            filters.push(format!("hue-rotate({v}deg)"));
        }
        if !filters.is_empty() {
            css.push_str(&format!("filter:{};", filters.join(" ")));
        }
        if let Some(v) = f32p(property_id::ROTATION_DEGREES) {
            if v != 0.0 {
                css.push_str(&format!("transform:rotate({v}deg);"));
            }
        }
        if let Some(v) = f32p(property_id::SCALE) {
            if v != 1.0 {
                css.push_str(&format!("transform:scale({v});"));
            }
        }
        // Shadow (accumulate x/y/radius/color — simplified to radius+color inline).
        if let (Some(r), Some(color_bits)) = (
            f32p(property_id::SHADOW_RADIUS),
            self.properties.get(&property_id::SHADOW_COLOR).copied(),
        ) {
            if r != 0.0 {
                let x = f32p(property_id::SHADOW_X).unwrap_or(0.0);
                let y = f32p(property_id::SHADOW_Y).unwrap_or(0.0);
                let color = self
                    .token_ref(property_id::SHADOW_COLOR)
                    .unwrap_or_else(|| rgba(color_bits));
                css.push_str(&format!("box-shadow:{x}px {y}px {r}px {color};"));
            }
        }
        if let Some(v) = self.token_ref(property_id::OPACITY) {
            css.push_str(&format!("opacity:{v};"));
        } else if let Some(v) = f32p(property_id::OPACITY) {
            if v < 1.0 {
                css.push_str(&format!("opacity:{v};"));
            }
        }
        if let Some(v) = f32p(property_id::Z_INDEX) {
            css.push_str(&format!("z-index:{};", v as i32));
        }

        // Enum-derived properties (previously Tailwind classes) now inline.
        // ALIGNMENT cross-axis (Leading=0, Center=1, Trailing=2, Fill=3 → default stretch).
        if let Some(v) = f32p(property_id::ALIGNMENT) {
            css.push_str(&format!(
                "align-items:{};",
                match v as u8 {
                    0 => "flex-start",
                    1 => "center",
                    2 => "flex-end",
                    _ => "stretch",
                }
            ));
        }
        // TEXT_ALIGNMENT (Leading=0, Center=1, Trailing=2).
        if let Some(v) = f32p(property_id::TEXT_ALIGNMENT) {
            css.push_str(&format!(
                "text-align:{};",
                match (v as u8).min(2) {
                    0 => "left",
                    1 => "center",
                    _ => "right",
                }
            ));
        }
        // TEXT_CASE (None=0, Uppercase=1, Lowercase=2).
        if let Some(v) = f32p(property_id::TEXT_CASE) {
            css.push_str(&format!(
                "text-transform:{};",
                match v as u8 {
                    1 => "uppercase",
                    2 => "lowercase",
                    _ => "none",
                }
            ));
        }
        // VISIBLE=0 → hidden.
        if let Some(bits) = self.properties.get(&property_id::VISIBLE) {
            if *bits == 0 {
                css.push_str("display:none;");
            }
        }
        // FONT_STYLE italic.
        if let Some(v) = f32p(property_id::FONT_STYLE) {
            if v != 0.0 {
                css.push_str("font-style:italic;");
            }
        }
        // FONT_DESIGN (Default=0, Serif=1, Rounded=2, Monospaced=3).
        if let Some(v) = f32p(property_id::FONT_DESIGN) {
            css.push_str(&format!(
                "font-family:{};",
                match v as u8 {
                    1 => "Georgia, 'Times New Roman', serif",
                    2 => "ui-rounded, system-ui, sans-serif",
                    3 => "ui-monospace, monospace",
                    _ => "inherit",
                }
            ));
        }
        // UNDERLINE / STRIKETHROUGH.
        let mut decoration = Vec::new();
        if let Some(v) = f32p(property_id::UNDERLINE) {
            if v != 0.0 {
                decoration.push("underline");
            }
        }
        if let Some(v) = f32p(property_id::STRIKETHROUGH) {
            if v != 0.0 {
                decoration.push("line-through");
            }
        }
        if !decoration.is_empty() {
            css.push_str(&format!("text-decoration:{};", decoration.join(" ")));
        }
        // CLIPS_TO_BOUNDS → overflow hidden.
        if let Some(v) = f32p(property_id::CLIPS_TO_BOUNDS) {
            if v != 0.0 {
                css.push_str("overflow:hidden;");
            }
        }
        // ALLOWS_HIT_TESTING (inverted: absent = allowed).
        if let Some(v) = f32p(property_id::ALLOWS_HIT_TESTING) {
            if v == 0.0 {
                css.push_str("pointer-events:none;");
            }
        }
        // COLOR_INVERT.
        if let Some(v) = f32p(property_id::COLOR_INVERT) {
            if v != 0.0 {
                css.push_str("filter:invert(1);");
            }
        }
        // TRUNCATION_MODE → ellipsis.
        if self.properties.contains_key(&property_id::TRUNCATION_MODE) {
            css.push_str("text-overflow:ellipsis;overflow:hidden;white-space:nowrap;");
        }

        css
    }

    /// Border CSS, decoded from `BORDER_WIDTH`/`BORDER_COLOR`/`BORDER_RADIUS`/
    /// `BORDER_EDGES` (empty when the node has no border).
    fn border_style(&self) -> String {
        let width = match self.token_ref(property_id::BORDER_WIDTH) {
            Some(v) => v,
            None => {
                let Some(width_bits) = self.properties.get(&property_id::BORDER_WIDTH) else {
                    return String::new();
                };
                format!("{}px", f32::from_bits(*width_bits))
            }
        };
        let color = match self.token_ref(property_id::BORDER_COLOR) {
            Some(v) => v,
            None => rgba(
                self.properties
                    .get(&property_id::BORDER_COLOR)
                    .copied()
                    .unwrap_or(0xFF00_0000),
            ),
        };
        let edges = self
            .properties
            .get(&property_id::BORDER_EDGES)
            .copied()
            .unwrap_or(border_edges::ALL);

        let mut css = String::new();
        for (flag, side) in [
            (border_edges::TOP, "top"),
            (border_edges::LEADING, "left"),
            (border_edges::BOTTOM, "bottom"),
            (border_edges::TRAILING, "right"),
        ] {
            if edges & flag != 0 {
                css.push_str(&format!("border-{side}:{width} solid {color};"));
            }
        }
        css
    }
}

/// Unpack a `0xAARRGGBB` color into `(r, g, b, alpha)` where `alpha` is `0..1`.
fn unpack_color(argb: u32) -> (u32, u32, u32, f32) {
    let r = (argb >> 16) & 0xFF;
    let g = (argb >> 8) & 0xFF;
    let b = argb & 0xFF;
    let a = ((argb >> 24) & 0xFF) as f32 / 255.0;
    (r, g, b, a)
}

/// A `0xAARRGGBB` color as a CSS `rgba(r,g,b,a)` string.
fn rgba(argb: u32) -> String {
    let (r, g, b, a) = unpack_color(argb);
    format!("rgba({r},{g},{b},{a})")
}

/// A `WIDTH`/`HEIGHT` hint as CSS: `FILL` (-1) → `100%`, `HUG_CONTENT` (-2) →
/// `fit-content`, otherwise pixels.
fn size_css(v: f32) -> String {
    if v == pathland_core::size::FILL {
        "100%".to_string()
    } else if v == pathland_core::size::HUG_CONTENT {
        "fit-content".to_string()
    } else {
        format!("{v}px")
    }
}

/// The column count of a `GRID` from its `WIDTH` property (cell-axis count);
/// `FILL`/absent → auto-fit.
fn grid_columns(node: &Node) -> Option<u32> {
    let w = node.f32_property(property_id::WIDTH, -1.0);
    if w <= 0.0 {
        None
    } else {
        Some(w.round() as u32)
    }
}

/// Convert days since the Unix epoch (negative = before 1970) to a Gregorian
/// `(year, month, day)` using the civil-from-days algorithm.
fn days_to_date(days: i32) -> (i32, u32, u32) {
    let z = i64::from(days) + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y as i32, m as u32, d as u32)
}

/// Millis of day → `(hours, minutes, seconds)`.
fn millis_to_hms(millis: u32) -> (u32, u32, u32) {
    let total = millis / 1000;
    (total / 3600, (total % 3600) / 60, total % 60)
}

/// Event-surfacing `data-*` attributes for a hydration client, from
/// `EVENT_LISTENERS` / `ACTION_ID` / `BINDING_ID`.
fn event_attrs(node: &Node) -> String {
    let mut attrs = String::new();
    if let Some(m) = node.properties.get(&property_id::EVENT_LISTENERS) {
        if *m != 0 {
            attrs.push_str(&format!(" data-event-listeners=\"{m}\""));
        }
    }
    if let Some(a) = node.properties.get(&property_id::ACTION_ID) {
        attrs.push_str(&format!(" data-action-id=\"{a}\""));
    }
    if let Some(b) = node.properties.get(&property_id::BINDING_ID) {
        attrs.push_str(&format!(" data-binding-id=\"{b}\""));
    }
    attrs
}

/// ARIA attributes from `ROLE` / `STATE` / `ENABLED`. The `ROLE` map is the
/// canonical `role_spec` (also generated into the DOM client), so a role
/// resolves to the same ARIA attribute on both renderers; roles that render as
/// a semantic element (or are conveyed by a native control element) emit no
/// attribute.
fn aria_attrs(node: &Node) -> String {
    let mut attrs = String::new();
    if let Some(bits) = node.properties.get(&property_id::ROLE) {
        let code = f32::from_bits(*bits) as u8;
        let kind = role_spec::shell_kind(node.component);
        if let Some(role) = role_spec::aria_role(kind, code) {
            attrs.push_str(&format!(" role=\"{role}\""));
        }
    }
    if let Some(bits) = node.properties.get(&property_id::STATE) {
        match f32::from_bits(*bits) as u8 {
            1 => attrs.push_str(" aria-disabled=\"true\""),
            3 => attrs.push_str(" aria-pressed=\"true\""),
            4 => attrs.push_str(" aria-selected=\"true\""),
            5 => attrs.push_str(" aria-expanded=\"true\""),
            6 => attrs.push_str(" aria-busy=\"true\""),
            _ => {}
        }
    }
    if let Some(bits) = node.properties.get(&property_id::ENABLED) {
        if *bits == 0 {
            attrs.push_str(" disabled");
        }
    }
    attrs
}

/// Decode a self-contained snapshot batch (opcodes + string section) into a
/// **transient** `id → Node` map. The map lives only for the duration of one
/// render call — the renderer retains nothing between calls.
fn decode(opcodes: &[Opcode], strings: &[u8]) -> (BTreeMap<u32, Node>, Tokens) {
    let mut nodes = BTreeMap::new();
    let mut tokens = Tokens::default();
    for op in opcodes {
        match op.category() {
            category::TREE => apply_tree(&mut nodes, op.command(), *op),
            category::STYLE => {
                if op.command() == style::SET_DESIGN_TOKEN {
                    // Global override: A = arenaRef (token path), B = valueType,
                    // C = value (for STRING, an arenaRef to the value string).
                    if let Some(path) = strings_str(strings, op.a()) {
                        let vt = (op.b() & 0xFF) as u8;
                        let value = if vt == value_type::STRING {
                            strings_str(strings, op.c())
                                .map(TokenValue::Str)
                                .unwrap_or(TokenValue::U32(0))
                        } else {
                            TokenValue::from_wire(vt, op.c()).unwrap_or(TokenValue::U32(op.c()))
                        };
                        tokens.set(&path, vt, value);
                    }
                } else {
                    apply_style(&mut nodes, op.command(), *op, strings);
                }
            }
            _ => {}
        }
    }
    (nodes, tokens)
}

/// Read a `[u32 len][utf8]` entry from the batch's string section at a relative offset.
fn strings_str(strings: &[u8], offset: u32) -> Option<String> {
    let offset = offset as usize;
    if offset + 4 > strings.len() {
        return None;
    }
    let len = u32::from_le_bytes(strings[offset..offset + 4].try_into().ok()?) as usize;
    let start = offset + 4;
    if start + len > strings.len() {
        return None;
    }
    std::str::from_utf8(&strings[start..start + len]).ok().map(str::to_owned)
}

// --- Design tokens (spec/TOKENS.md) ---

/// `SET_DESIGN_TOKEN` overrides collected from a snapshot batch. `base` holds
/// light tokens (keyed by full path); `dark` holds `dark.`-prefixed overrides
/// (keyed by the bare path). Values are resolved [`TokenValue`]s (STRING values
/// are resolved from the batch's string section at decode time).
#[derive(Debug, Default, Clone)]
struct Tokens {
    base: BTreeMap<String, (u8, TokenValue)>,
    dark: BTreeMap<String, (u8, TokenValue)>,
}

impl Tokens {
    fn set(&mut self, path: &str, value_type: u8, value: TokenValue) {
        if let Some(bare) = path.strip_prefix("dark.") {
            self.dark.insert(bare.to_string(), (value_type, value));
        } else {
            self.base.insert(path.to_string(), (value_type, value));
        }
    }

    /// Render the overrides as CSS rules: base tokens as `:root` rules, dark
    /// overrides inside `@media (prefers-color-scheme: dark)` — the browser
    /// resolves the scheme natively, so SSR needs no client scheme knowledge.
    fn css(&self) -> String {
        let mut css = String::new();
        for (path, (vt, value)) in &self.base {
            css.push_str(&format!(
                ":root{{{}:{};}}",
                token_to_css_var(path),
                token_css_value(path, *vt, value)
            ));
        }
        if !self.dark.is_empty() {
            let rules: String = self
                .dark
                .iter()
                .map(|(path, (vt, value))| {
                    format!(":root{{{}:{};}}", token_to_css_var(path), token_css_value(path, *vt, value))
                })
                .collect();
            css.push_str(&format!("@media (prefers-color-scheme: dark){{{rules}}}"));
        }
        css
    }
}

/// The canonical CSS custom property for a token path: `--pl-` prefix, `.` →
/// `-`. The `dark.` scheme prefix is stripped — the dark variant overrides the
/// same variable inside the media query (spec/TOKENS.md; the naming rules live
/// in [`token_spec`], which `pathland-ts-codegen` mirrors into the DOM client).
fn token_to_css_var(path: &str) -> String {
    let bare = path.strip_prefix(token_spec::DARK_PREFIX).unwrap_or(path);
    let name: String = bare
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() || c == '-' || c == '_' { c } else { '-' })
        .collect();
    format!("{}{name}", token_spec::VAR_PREFIX)
}

/// Token paths whose F32 values are CSS lengths (emitted with `px`).
fn is_length_token(path: &str) -> bool {
    for prefix in token_spec::LENGTH_PREFIXES {
        if path.starts_with(prefix) {
            return true;
        }
    }
    for (prefix, suffix) in token_spec::LENGTH_PREFIX_SUFFIX {
        if path.starts_with(prefix) && path.ends_with(suffix) {
            return true;
        }
    }
    if token_spec::LENGTH_EXACT.contains(&path) {
        return true;
    }
    path.starts_with("elevation.")
        && token_spec::LENGTH_ELEVATION_SUFFIXES
            .iter()
            .any(|s| path.ends_with(s))
}

/// Render a token override value as a CSS value string: `STRING` values are
/// single-quoted (escaped); `F32` length tokens append `px`.
fn token_css_value(path: &str, _value_type: u8, value: &TokenValue) -> String {
    match value {
        TokenValue::Str(s) => format!("'{}'", s.replace('\\', "\\\\").replace('\'', "\\'")),
        TokenValue::Color(argb) => rgba(*argb),
        TokenValue::F32(v) => {
            if is_length_token(path) {
                format!("{v}px")
            } else {
                format!("{v}")
            }
        }
        TokenValue::I32(v) => format!("{v}"),
        TokenValue::U32(v) => format!("{v}"),
        TokenValue::U8(v) => format!("{v}"),
    }
}

/// Resolve a `DESIGN_TOKEN` property reference to a CSS expression. The
/// generative `space.<N>` family resolves to `calc(var(--pl-space-base) * N)`;
/// every other token resolves to `var(--pl-<path>)`.
fn resolve_token_ref(path: &str) -> String {
    let bare = path.strip_prefix(token_spec::DARK_PREFIX).unwrap_or(path);
    if let Some(rest) = bare.strip_prefix(token_spec::SPACE_FAMILY) {
        if rest.parse::<f64>().is_ok() {
            return format!("calc(var(--pl-space-base) * {rest})");
        }
    }
    format!("var({})", token_to_css_var(bare))
}

fn apply_tree(nodes: &mut BTreeMap<u32, Node>, command: u8, op: Opcode) {
    match command {
        tree::CREATE_NODE => {
            let id = op.a();
            let component = op.b() as u16;
            nodes.insert(id, Node::new(component));
        }
        tree::DELETE_NODE => {
            nodes.remove(&op.a());
        }
        tree::INSERT_CHILD => {
            let (parent, child) = (op.a(), op.b());
            if let Some(node) = nodes.get_mut(&parent) {
                let index = op.c();
                if index == pathland_core::APPEND {
                    node.children.push(child);
                } else {
                    let index = (index as usize).min(node.children.len());
                    node.children.insert(index, child);
                }
            }
        }
        tree::REMOVE_CHILD => {
            let (parent, child) = (op.a(), op.b());
            if let Some(node) = nodes.get_mut(&parent) {
                node.children.retain(|&c| c != child);
            }
        }
        tree::MOVE_CHILD => {
            let (parent, child, index) = (op.a(), op.b(), op.c());
            if let Some(node) = nodes.get_mut(&parent) {
                node.children.retain(|&c| c != child);
                let index = (index as usize).min(node.children.len());
                node.children.insert(index, child);
            }
        }
        _ => {}
    }
}

fn apply_style(nodes: &mut BTreeMap<u32, Node>, command: u8, op: Opcode, strings: &[u8]) {
    match command {
        style::SET_TEXT => {
            if let Some(text) = strings_str(strings, op.b()) {
                if let Some(node) = nodes.get_mut(&op.a()) {
                    node.text = Some(text);
                }
            }
        }
        style::SET_PROPERTY => {
            let property = (op.b() & 0xFFFF) as u16;
            if let Some(node) = nodes.get_mut(&op.a()) {
                let vt = (op.b() >> 16) as u8;
                if vt == value_type::STRING {
                    if let Some(text) = strings_str(strings, op.c()) {
                        node.strings.insert(property, text);
                    }
                } else if vt == value_type::DESIGN_TOKEN {
                    // C = arenaRef to the token path; resolved at render time to
                    // `var(--pl-…)` / `calc(...)` (see `Node::token_ref`).
                    if let Some(path) = strings_str(strings, op.c()) {
                        node.token_refs.insert(property, path);
                    }
                } else {
                    node.properties.insert(property, op.c());
                }
            }
        }
        style::SET_DATE => {
            if let Some(node) = nodes.get_mut(&op.a()) {
                // B = days since epoch (I32), C = millis of day (U32).
                node.date = Some((op.b() as i32, op.c()));
            }
        }
        _ => {}
    }
}

/// A **stateless, streaming** HTML renderer. Each render call decodes a
/// self-contained snapshot batch into a transient map, walks it once, and
/// streams HTML text out — zero state retained across calls. A pure function
/// of the opcode stream (Renderer Statelessness).
#[derive(Debug, Clone, Copy)]
pub struct HtmlRenderer {
    /// When enabled, every rendered node is prefixed with an HTML comment
    /// describing its component type and the modifiers (style properties)
    /// applied to it (`<!-- #1 VStack: spacing=4, alignment=Fill -->`). A
    /// debugging aid — off by default so production SSR stays lean.
    debug_comments: bool,
}

impl HtmlRenderer {
    /// Create a renderer (stateless; the same value serves every render).
    #[must_use]
    pub fn new() -> Self {
        Self {
            debug_comments: false,
        }
    }

    /// Enable/disable debug comments. When on, each rendered node is prefixed
    /// with an HTML comment naming its component and the modifiers applied
    /// (see [`crate::debug`]).
    #[must_use]
    pub fn with_debug_comments(mut self, on: bool) -> Self {
        self.debug_comments = on;
        self
    }

    /// Whether debug comments are enabled.
    #[must_use]
    pub fn debug_comments(&self) -> bool {
        self.debug_comments
    }

    /// Render the subtree rooted at `root` as a full HTML document.
    #[must_use]
    pub fn render_document(&self, opcodes: &[Opcode], strings: &[u8], root: u32) -> String {
        let (nodes, tokens) = decode(opcodes, strings);
        let body = self.render_node(&nodes, root);
        // Token overrides render as their own `<style data-pathland-tokens>`
        // element AFTER the built-in block so their `:root` variables win the
        // cascade (same specificity, later wins) — matching the JS DOM client's
        // `style[data-pathland-tokens]` element. No overrides → no element.
        let token_rules = tokens.css();
        let token_style = if token_rules.is_empty() {
            String::new()
        } else {
            format!("<style data-pathland-tokens>{token_rules}</style>\n")
        };
        format!(
            "<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n\
             <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\
             <title>Pathland</title>\n\
             <link rel=\"preconnect\" href=\"https://rsms.me/\">\n\
             <link rel=\"stylesheet\" href=\"https://rsms.me/inter/inter.css\">\n\
             {}{}\n</head>\n<body>{body}</body>\n</html>\n",
            css::STYLE,
            token_style
        )
    }

    /// Render the subtree rooted at `root` as an HTML fragment (no `<html>`).
    /// `SET_DESIGN_TOKEN` overrides are applied to the document head by
    /// `render_document`; a fragment is assumed to be embedded in a document
    /// that already defines the token variables.
    #[must_use]
    pub fn render_fragment(&self, opcodes: &[Opcode], strings: &[u8], root: u32) -> String {
        let (nodes, _) = decode(opcodes, strings);
        self.render_node(&nodes, root)
    }

    fn render_node(&self, nodes: &BTreeMap<u32, Node>, id: u32) -> String {
        let Some(node) = nodes.get(&id) else {
            return String::new();
        };
        let children: String = node
            .children
            .iter()
            .map(|&child| self.render_node(nodes, child))
            .collect();
        let mut data_id = format!(" data-pathland-id=\"{id}\"");
        data_id.push_str(&slot_attrs(node));
        let css = format!("{}{}", node.style_css(), node.border_style());
        let style = style_attr(&css);
        let event = event_attrs(node);
        let aria = aria_attrs(node);
        // A semantic role may retag a generic div/span shell (role_spec);
        // control components keep their native element.
        let kind = role_spec::shell_kind(node.component);
        let semantic = role_spec::semantic_tag(kind, node.role_code());

        let element = match node.component {
            component_type::VSTACK => wrap_stack(id, "column", semantic, node, &children, &css, &event, &aria),
            component_type::HSTACK => wrap_stack(id, "row", semantic, node, &children, &css, &event, &aria),
            component_type::LAZY_VSTACK => {
                wrap_stack(id, "column", semantic, node, &children, &css, &event, &aria)
            }
            component_type::LAZY_HSTACK => {
                wrap_stack(id, "row", semantic, node, &children, &css, &event, &aria)
            }
            component_type::TEXT => {
                // A TEXT's tag is resolved by typography + role: a heading
                // `TEXT_STYLE` (LargeTitle…Headline) is always a heading; else
                // `ROLE_HEADER` → `<h2>`, `ROLE_PARAGRAPH` → `<p>`; else `<span>`.
                let tag = role_spec::text_tag(kind, node.role_code(), node.text_style_code())
                    .unwrap_or("span");
                let text = escape(node.text.as_deref().unwrap_or_default());
                format!("<{tag}{data_id}{event}{aria}{style}>{text}</{tag}>")
            }
            component_type::BUTTON => {
                // Composite Override Mode: children present → custom body.
                let body = if node.children.is_empty() {
                    escape(node.text.as_deref().unwrap_or_default())
                } else {
                    children
                };
                let button_class = class_attr("pathland-button");
                format!("<button{data_id}{event}{aria}{button_class}{style}>{body}</button>")
            }
            component_type::TOGGLE => {
                let toggle_style = node.f32_property(property_id::TOGGLE_STYLE, 0.0).round() as u8;
                let checked = if node.checked() { " checked" } else { "" };
                let body = if node.children.is_empty() {
                    format!(
                        "<span class=\"pathland-text\">{}</span>",
                        escape(node.text.as_deref().unwrap_or_default())
                    )
                } else {
                    format!("<div class=\"pathland-custom-body\">{children}</div>")
                };
                let toggle_class = class_attr("pathland-toggle");
                match toggle_style {
                    1 => format!(
                        "<label{data_id}{event}{aria}{toggle_class}{style}><input type=\"checkbox\"{checked}>{body}</label>"
                    ),
                    2 => {
                        let pressed = if node.checked() { "true" } else { "false" };
                        format!(
                            "<button{data_id}{event}{aria} type=\"button\" aria-pressed=\"{pressed}\"{style}>{body}</button>"
                        )
                    }
                    _ => format!(
                        "<label{data_id}{event}{aria}{toggle_class}{style}><input type=\"checkbox\" role=\"switch\"{checked}>{body}</label>"
                    ),
                }
            }
            component_type::SPACER => {
                let tag = semantic.unwrap_or("div");
                let combined = format!("flex:1;{css}");
                let spacer_style = style_attr(&combined);
                format!("<{tag}{data_id}{event}{aria}{spacer_style}></{tag}>")
            }
            component_type::SLIDER => {
                let min = node.f32_property(property_id::MIN_VALUE, 0.0);
                let max = node.f32_property(property_id::MAX_VALUE, 1.0);
                let value = node.f32_property(property_id::VALUE, min);
                let body = if node.children.is_empty() {
                    format!(
                        "<span class=\"pathland-text\">{}</span>",
                        escape(node.text.as_deref().unwrap_or_default())
                    )
                } else {
                    format!("<div class=\"pathland-custom-body\">{children}</div>")
                };
                let slider_class = class_attr("pathland-slider");
                format!(
                    "<label{data_id}{event}{aria}{slider_class}{style}><input type=\"range\" min=\"{min}\" max=\"{max}\" step=\"any\" value=\"{value}\">{body}</label>"
                )
            }
            component_type::TEXT_FIELD => {
                let value = escape(node.text.as_deref().unwrap_or_default());
                let label = escape(
                    node.strings
                        .get(&property_id::LABEL)
                        .map(String::as_str)
                        .unwrap_or_default(),
                );
                let prompt = escape(
                    node.strings
                        .get(&property_id::PROMPT)
                        .map(String::as_str)
                        .unwrap_or_default(),
                );
                let input_type = if node.f32_property(property_id::IS_SECURE, 0.0) != 0.0 {
                    "password"
                } else {
                    "text"
                };
                let textfield_class = class_attr("pathland-textfield");
                format!(
                    "<label{data_id}{event}{aria}{textfield_class}{style}><span class=\"pathland-label\">{label}</span><input class=\"pathland-input\" type=\"{input_type}\" value=\"{value}\" placeholder=\"{prompt}\"></label>"
                )
            }
            component_type::TEXT_EDITOR => {
                let value = escape(node.text.as_deref().unwrap_or_default());
                format!("<textarea{data_id}{event}{aria} class=\"pathland-input\" rows=\"4\"{style}>{value}</textarea>")
            }
            component_type::IMAGE => {
                let src = escape(
                    node.strings
                        .get(&property_id::IMAGE_SOURCE)
                        .map(String::as_str)
                        .unwrap_or_default(),
                );
                format!("<img{data_id}{event}{aria} src=\"{src}\"{style}>")
            }
            component_type::COLOR => {
                let tag = semantic.unwrap_or("div");
                let color = node.u32_property(property_id::COLOR, 0xFF00_0000);
                // Layout-greedy (SwiftUI Color): expands to the available space
                // unless a size modifier constrains it.
                format!(
                    "<{tag}{data_id}{event}{aria} style=\"flex:1 1 auto;align-self:stretch;background-color:{};{css}\">{children}</{tag}>",
                    rgba(color)
                )
            }
            component_type::SHAPE => {
                let kind = node.f32_property(property_id::SHAPE_KIND, 0.0).round() as u8;
                let fill = node.u32_property(property_id::COLOR, 0xFF00_0000);
                let w = node.f32_property(property_id::WIDTH, 100.0);
                let h = node.f32_property(property_id::HEIGHT, 100.0);
                let base = format!(
                    "width:{};height:{};background-color:{};{css}",
                    size_css(w),
                    size_css(h),
                    rgba(fill)
                );
                // A semantic role retags the CSS-shape divs; the Path branch is an
                // `<svg>` and ignores the role.
                let tag = semantic.unwrap_or("div");
                match kind {
                    0 | 4 => format!("<{tag}{data_id}{event}{aria} style=\"{base}border-radius:50%;\"></{tag}>"),
                    2 => {
                        let r = node.f32_property(property_id::BORDER_RADIUS, 8.0);
                        format!("<{tag}{data_id}{event}{aria} style=\"{base}border-radius:{r}px;\"></{tag}>")
                    }
                    3 => format!("<{tag}{data_id}{event}{aria} style=\"{base}border-radius:9999px;\"></{tag}>"),
                    5 => format!(
                        "<svg{data_id}{event}{aria} width=\"100\" height=\"100\" viewBox=\"0 0 100 100\"><rect width=\"100\" height=\"100\" fill=\"{}\"/></svg>",
                        rgba(fill)
                    ),
                    _ => format!("<{tag}{data_id}{event}{aria} style=\"{base}\"></{tag}>"),
                }
            }
            component_type::DIVIDER => {
                let width = node.f32_property(property_id::BORDER_WIDTH, 1.0);
                let color = node
                    .properties
                    .get(&property_id::COLOR)
                    .copied()
                    .map(rgba)
                    .unwrap_or_else(|| "rgba(0,0,0,0.2)".to_string());
                format!(
                    "<div{data_id}{event}{aria} style=\"height:0;border-top:{width}px solid {color};\"></div>"
                )
            }
            component_type::PROGRESS_VIEW => {
                let indeterminate = node.f32_property(property_id::IS_INDETERMINATE, 0.0) != 0.0
                    || node.f32_property(property_id::PROGRESS, -1.0) < 0.0;
if indeterminate {
                    let spinner_class = class_attr("pathland-spinner");
                    format!("<div{data_id}{spinner_class}{style}></div>")
                } else {
                    let value = node.f32_property(property_id::PROGRESS, 0.0);
                    let max = node.f32_property(property_id::MAX_VALUE, 1.0);
                    format!(
                        "<progress{data_id}{event}{aria} value=\"{value}\" max=\"{max}\"{style}></progress>"
                    )
                }
            }
            component_type::GAUGE => {
                let min = node.f32_property(property_id::MIN_VALUE, 0.0);
                let max = node.f32_property(property_id::MAX_VALUE, 1.0);
                let value = node.f32_property(property_id::VALUE, min);
                let pct = if max > min {
                    ((value - min) / (max - min)).clamp(0.0, 1.0) * 100.0
                } else {
                    0.0
                };
                let gauge_class = class_attr("pathland-gauge");
                // The bounds ride as `data-min`/`data-max` so the DOM client can
                // recompute the percentage when VALUE changes (its gauge handler
                // reads them), mirroring the stepper's `.pathland-stepper-range`.
                format!(
                    "<div{data_id}{event}{aria}{gauge_class} data-min=\"{min}\" data-max=\"{max}\"{style}><div style=\"width:{pct}%\"></div></div>"
                )
            }
            component_type::GRID | component_type::LAZY_VGRID | component_type::LAZY_HGRID => {
                let tag = semantic.unwrap_or("div");
                let cols = grid_columns(node);
                let grid_css = grid_style(cols, node.component == component_type::LAZY_HGRID);
                let combined = format!("{grid_css}{css}");
                let grid_style = style_attr(&combined);
                format!("<{tag}{data_id}{event}{aria}{grid_style}>{children}</{tag}>")
            }
            component_type::SCROLLVIEW => {
                let tag = semantic.unwrap_or("div");
                let combined = format!("overflow:auto;{css}");
                let scroll_style = style_attr(&combined);
                format!("<{tag}{data_id}{event}{aria}{scroll_style}>{children}</{tag}>")
            }
            component_type::ZSTACK => {
                let tag = semantic.unwrap_or("div");
                let inner: String = node
                    .children
                    .iter()
                    .map(|&child| {
                        let child_html = self.render_node(nodes, child);
                        if child_html.is_empty() {
                            String::new()
                        } else {
                            format!("<div style=\"position:absolute;inset:0\">{child_html}</div>")
                        }
                    })
                    .collect();
                let combined = format!("position:relative;width:100%;height:100%;{css}");
                let zstyle = style_attr(&combined);
                format!("<{tag}{data_id}{event}{aria}{zstyle}>{inner}</{tag}>")
            }
            component_type::STEPPER => {
                let min = node.f32_property(property_id::MIN_VALUE, 0.0);
                let max = node.f32_property(property_id::MAX_VALUE, 100.0);
                let value = node.f32_property(property_id::VALUE, min);
                let step = node.f32_property(property_id::STEP_VALUE, 1.0);
                // Composite shell matching the DOM client's `stepperShell()`
                // (lib/typescript/src/elements.ts): the +/- buttons and a hidden
                // `.pathland-stepper-range` span carrying the bounds for the
                // client's click math. The value is displayed in the first span,
                // rounded to 2 decimals like the client.
                let display = format!("{}", (value * 100.0).round() / 100.0);
                let stepper_class = class_attr("pathland-stepper");
                format!(
                    "<div{data_id}{event}{aria}{stepper_class}{style}><button type=\"button\" data-step=\"-1\">−</button><span>{display}</span><button type=\"button\" data-step=\"1\">+</button><span class=\"pathland-stepper-range\" hidden data-min=\"{min}\" data-max=\"{max}\" data-step=\"{step}\"></span></div>"
                )
            }
            component_type::DATE_PICKER => {
                let mode = node.f32_property(property_id::DATE_PICKER_MODE, 0.0).round() as u8;
                let (t, value) = match node.date {
                    Some((days, millis)) => match mode {
                        1 => {
                            let (hh, mm, _) = millis_to_hms(millis);
                            ("time", format!("{hh:02}:{mm:02}"))
                        }
                        2 => {
                            let (y, m, d) = days_to_date(days);
                            let (hh, mm, _) = millis_to_hms(millis);
                            (
                                "datetime-local",
                                format!("{y:04}-{m:02}-{d:02}T{hh:02}:{mm:02}"),
                            )
                        }
                        _ => {
                            let (y, m, d) = days_to_date(days);
                            ("date", format!("{y:04}-{m:02}-{d:02}"))
                        }
                    },
                    None => ("date", String::new()),
                };
                format!("<input{data_id}{event}{aria} type=\"{t}\" value=\"{value}\"{style}>")
            }
            component_type::PICKER => {
                let selected = node.u32_property(property_id::SELECTION, 0);
                let options: String = node
                    .children
                    .iter()
                    .enumerate()
                    .map(|(i, &child)| {
                        let label = nodes
                            .get(&child)
                            .and_then(|n| n.text.clone())
                            .unwrap_or_default();
                        let sel = if i as u32 == selected { " selected" } else { "" };
                        // Each option carries the child node's id so the DOM
                        // client can hydrate/reconcile it against the child's
                        // own TREE/STYLE deltas.
                        format!(
                            "<option data-pathland-id=\"{child}\" value=\"{i}\"{sel}>{}</option>",
                            escape(&label)
                        )
                    })
                    .collect();
                format!("<select{data_id}{event}{aria}{style}>{options}</select>")
            }
            component_type::MENU => {
                // Composite shell matching the DOM client's `menuShell()`
                // (lib/typescript/src/elements.ts): the trigger holds the label,
                // and TREE children are routed into `.pathland-menu-items` (the
                // client's `childrenContainer`). `role="menu"` is the control's
                // intrinsic semantics (not a `ROLE` property).
                let label = escape(node.text.as_deref().unwrap_or_default());
                let menu_class = class_attr("pathland-menu");
                format!(
                    "<div{data_id}{event}{aria}{menu_class} role=\"menu\"{style}><div class=\"pathland-menu-trigger\">{label}</div><div class=\"pathland-menu-items\">{children}</div></div>"
                )
            }
            component_type::COLOR_PICKER => {
                let color = node.u32_property(property_id::COLOR_VALUE, 0xFF00_0000);
                let hex = format!(
                    "#{:02x}{:02x}{:02x}",
                    (color >> 16) & 0xFF,
                    (color >> 8) & 0xFF,
                    color & 0xFF
                );
                format!("<input{data_id}{event}{aria} type=\"color\" value=\"{hex}\"{style}>")
            }
            component_type::COMMENT => String::new(),
            _ => String::new(),
        };
        if self.debug_comments {

// The DOM renderer's native element mapping: create the DOM shell for a node of
// the given component. Used when TREE deltas create nodes at runtime (the SSR
// path renders the shell server-side with Tailwind classes).

import {
  COMPONENT_BUTTON,
  COMPONENT_COLOR,
  COMPONENT_COLOR_PICKER,
  COMPONENT_COMMENT,
  COMPONENT_DATE_PICKER,
  COMPONENT_DIVIDER,
  COMPONENT_GAUGE,
  COMPONENT_GRID,
  COMPONENT_HSTACK,
  COMPONENT_IMAGE,
  COMPONENT_LAZY_HGRID,
  COMPONENT_LAZY_HSTACK,
  COMPONENT_LAZY_VGRID,
  COMPONENT_LAZY_VSTACK,
  COMPONENT_MENU,
  COMPONENT_PICKER,
  COMPONENT_PROGRESS_VIEW,
  COMPONENT_SCROLLVIEW,
  COMPONENT_SHAPE,
  COMPONENT_SLIDER,
  COMPONENT_SPACER,
  COMPONENT_STEPPER,
  COMPONENT_TEXT,
  COMPONENT_TEXT_EDITOR,
  COMPONENT_TEXT_FIELD,
  COMPONENT_TOGGLE,
  COMPONENT_VSTACK,
  COMPONENT_ZSTACK,
} from "./constants";

/** Create the DOM shell for a node of {@code component}. Returns a Node (elements or an inert comment). */
export function createElement(component: number): Node {
  switch (component) {
    case COMPONENT_VSTACK:
    case COMPONENT_LAZY_VSTACK:
      return flexBox("column");
    case COMPONENT_HSTACK:
    case COMPONENT_LAZY_HSTACK:
      return flexBox("row");
    case COMPONENT_ZSTACK: {
      const el = document.createElement("div");
      el.style.position = "relative";
      el.style.width = "100%";
      el.style.height = "100%";
      return el;
    }
    case COMPONENT_GRID:
    case COMPONENT_LAZY_VGRID:
    case COMPONENT_LAZY_HGRID: {
      const el = document.createElement("div");
      el.style.display = "grid";
      // Lazy horizontal grids flow into auto columns (mirrors the Rust SSR
      // renderer's `grid-auto-flow:column;grid-auto-columns:1fr`).
      if (component === COMPONENT_LAZY_HGRID) {
        el.style.gridAutoFlow = "column";
        el.style.gridAutoColumns = "1fr";
      }
      return el;
    }
    case COMPONENT_SCROLLVIEW: {
      const el = document.createElement("div");
      el.style.overflow = "auto";
      return el;
    }
    case COMPONENT_TEXT:
      return document.createElement("span");
    case COMPONENT_BUTTON: {
      const el = document.createElement("button");
      el.className = "pathland-button"; // mirror the Rust renderer's SSR class
      return el;
    }
    case COMPONENT_IMAGE: {
      const el = document.createElement("img");
      el.alt = "";
      return el;
    }
    case COMPONENT_COLOR: {
      // Layout-greedy (SwiftUI Color): expands to the available space unless a
      // size modifier constrains it (mirrors the Rust SSR renderer's
      // `flex:1 1 auto;align-self:stretch`).
      const el = document.createElement("div");
      el.style.flex = "1 1 auto";
      el.style.alignSelf = "stretch";
      return el;
    }
    case COMPONENT_SHAPE:
      return document.createElement("div");
    case COMPONENT_GAUGE: {
      // `<div class="pathland-gauge"><div></div></div>` — the bar width is set from
      // the VALUE property at apply time (mirrors the Rust renderer's SSR markup).
      const el = document.createElement("div");
      el.className = "pathland-gauge";
      el.append(document.createElement("div"));
      return el;
    }
    case COMPONENT_DIVIDER: {
      // `<div style="height:0;border-top:1px solid rgba(0,0,0,0.2)">` — mirrors
      // the Rust SSR renderer's default divider (a div with only a top border, so
      // it is free of the `<hr>` element's UA margins/styles). BORDER_WIDTH /
      // COLOR deltas override border-top at apply time.
      const el = document.createElement("div");
      el.style.height = "0";
      el.style.borderTop = "1px solid rgba(0,0,0,0.2)";
      return el;
    }
    case COMPONENT_SPACER: {
      const el = document.createElement("div");
      el.style.flex = "1";
      return el;
    }
    case COMPONENT_PROGRESS_VIEW: {
      const el = document.createElement("progress");
      el.max = 1;
      return el;
    }
    case COMPONENT_TEXT_EDITOR: {
      const el = document.createElement("textarea");
      el.className = "pathland-input";
      el.setAttribute("rows", "4"); // mirrors the Rust SSR renderer
      return el;
    }
    case COMPONENT_TEXT_FIELD:
      return textFieldShell();
    case COMPONENT_TOGGLE:
      return toggleShell();
    case COMPONENT_SLIDER:
      return sliderShell();
    case COMPONENT_STEPPER:
      return stepperShell();
    case COMPONENT_PICKER:
      return document.createElement("select");
    case COMPONENT_MENU:
      return menuShell();
    case COMPONENT_COLOR_PICKER: {
      const el = document.createElement("input");
      el.type = "color";
      return el;
    }
    case COMPONENT_DATE_PICKER: {
      const el = document.createElement("input");
      el.type = "date";
      return el;
    }
    case COMPONENT_COMMENT:
      return document.createComment("");
    default:
      return document.createElement("div");
  }
}

function flexBox(direction: "column" | "row"): HTMLElement {
  const el = document.createElement("div");
  el.style.display = "flex";
  el.style.flexDirection = direction;
  // Cross-axis default is stretch (the Rust SSR renderer's `align-items` when no
  // ALIGNMENT property is set); an ALIGNMENT delta overrides it.
  el.style.alignItems = "stretch";
  return el;
}

/** `<label class="pathland-textfield"><span class="pathland-label"></span><input type="text"></label>` */
function textFieldShell(): HTMLElement {
  const label = document.createElement("label");
  label.className = "pathland-textfield";
  const span = document.createElement("span");
  span.className = "pathland-label";
  const input = document.createElement("input");
  input.type = "text";
  input.className = "pathland-input";
  label.append(span, input);
  return label;
}

/** `<label class="pathland-toggle"><input type="checkbox"><span class="pathland-text"></span></label>` */
function toggleShell(): HTMLElement {
  const label = document.createElement("label");
  label.className = "pathland-toggle";
  const input = document.createElement("input");
  input.type = "checkbox";
  const span = document.createElement("span");
  span.className = "pathland-text";
  label.append(input, span);
  return label;
}

/** `<label class="pathland-slider"><input type="range" step="any"><span class="pathland-text"></span></label>` */
function sliderShell(): HTMLElement {
  const label = document.createElement("label");
  label.className = "pathland-slider";
  const input = document.createElement("input");
  input.type = "range";
  input.step = "any";
  const span = document.createElement("span");
  span.className = "pathland-text";
  label.append(input, span);
  return label;
}

/** `<div class="pathland-stepper"><button data-step="-1">−</button><span></span><button data-step="1">+</button><span class="pathland-stepper-range" hidden></span></div>` */
function stepperShell(): HTMLElement {
  const el = document.createElement("div");
  el.className = "pathland-stepper";
  const minus = document.createElement("button");
  minus.type = "button";
  minus.dataset.step = "-1";
  minus.textContent = "−";
  const value = document.createElement("span");
  const plus = document.createElement("button");
  plus.type = "button";
  plus.dataset.step = "1";
  plus.textContent = "+";
  const range = document.createElement("span");
  range.className = "pathland-stepper-range";
  range.hidden = true;
  el.append(minus, value, plus, range);
  return el;
}

/** `<div class="pathland-menu"><div class="pathland-menu-trigger"></div><div class="pathland-menu-items"></div></div>` */
function menuShell(): HTMLElement {
  const el = document.createElement("div");
  el.className = "pathland-menu";
  // `role="menu"` is the control's intrinsic semantics (mirrors the Rust SSR
  // renderer); the `ROLE` property no longer carries control roles.
  el.setAttribute("role", "menu");
  const trigger = document.createElement("div");
  trigger.className = "pathland-menu-trigger";
  const items = document.createElement("div");
  items.className = "pathland-menu-items";
  el.append(trigger, items);
  return el;
}

/**
 * The container a node's TREE children are inserted into. Most nodes append
 * children directly; composite shells route them into their label/trigger span.
 */
export function childrenContainer(node: Node): Node | null {
  if (node instanceof HTMLElement) {
    if (node.classList.contains("pathland-menu")) {
      return node.querySelector(".pathland-menu-items");
    }
    if (node.classList.contains("pathland-toggle") || node.classList.contains("pathland-slider")) {
      return node.querySelector(".pathland-text");
    }
    if (node.classList.contains("pathland-textfield")) {
      return node.querySelector(".pathland-label");
    }
  }
  return node;
}

// Delta application: decode each opcode and apply it to the DOM via the
// retained `id → Node` registry. STYLE deltas mutate the hydrated element in
// place; TREE deltas build the element shell and insert/remove/move it; META
// deltas reset/environment.

import {
  CAT_META,
  CAT_STYLE,
  CAT_TREE,
  CMD_CREATE_NODE,
  CMD_DELETE_NODE,
  CMD_ENVIRONMENT,
  CMD_INSERT_CHILD,
  CMD_MOVE_CHILD,
  CMD_REMOVE_CHILD,
  CMD_RESET,
  CMD_SET_DATE,
  CMD_SET_DESIGN_TOKEN,
  CMD_SET_PROPERTY,
  CMD_SET_TEXT,
  COMPONENT_COLOR,
  COMPONENT_GRID,
  COMPONENT_LAZY_HGRID,
  COMPONENT_LAZY_VGRID,
  COMPONENT_PICKER,
  COMPONENT_PROGRESS_VIEW,
  COMPONENT_SHAPE,
  COMPONENT_TEXT,
  COMPONENT_ZSTACK,
  PROP_BINDING_ID,
  PROP_COLOR,
  PROP_COLOR_VALUE,
  PROP_ENABLED,
  PROP_FONT_FAMILY,
  PROP_IMAGE_SOURCE,
  PROP_IS_INDETERMINATE,
  PROP_LABEL,
  PROP_NAV_CHROME,
  PROP_NAV_DEPTH,
  PROP_PROGRESS,
  PROP_PROMPT,
  PROP_ROLE,
  PROP_ROUTE,
  PROP_SELECTED,
  PROP_SELECTION,
  PROP_TEXT,
  PROP_TEXT_STYLE,
  PROP_VALUE,
  PROP_WIDTH,
  VAL_DESIGN_TOKEN,
  VAL_STRING,
  VAL_U8,
} from "./constants";
import type { Batch, Opcode } from "./plpl";
import { readString } from "./plpl";
import { childrenContainer, createElement } from "./elements";
import { applyEnabled, applyProperty, applyTokenRefProperty } from "./classes";
import { createTokenSink, applyDesignToken, type DesignTokenSink } from "./tokens";
import {
  GENERIC_COMPONENTS,
  NATIVE_ROLE_COMPONENTS,
  ariaRole,
  textTag,
} from "./generated/role-spec";
import { argbToHex, argbToRgba, daysToIso, f32FromBits, millisToTime } from "./format";

/** Component type per retained node, so STYLE/TREE application can special-case
 *  per component (a ZSTACK child's absolute positioning, a ProgressView's
 *  spinner/progress morph) without baking it into the DOM. */
const componentByNode = new WeakMap<Node, number>();

/** The last `ROLE` code applied per element (morphing needs both role and text
 *  style to resolve the effective tag). */
const roleByNode = new WeakMap<HTMLElement, number>();

/** The last `TEXT_STYLE` code applied per element, if any. */
const textStyleByNode = new WeakMap<HTMLElement, number>();

/** The retained `node id → DOM Node` registry the renderer works against. */
export interface DomRenderer {
  byId: Map<number, Node>;
  /**
   * Optional hook invoked when a slot's `ROUTE` property changes — the host wires it
   * to `history.pushState` so the browser URL mirrors the app's navigation (spec
   * DSL.md §4.5). Not called on hydrate (the URL is already correct).
   */
  onRoute?: (path: string) => void;
  /**
   * Optional hook invoked when the renderer's default back button (a
   * `PlatformDefault` nav slot at depth > 1) is clicked — the host wires it to a
   * `NAVIGATE` event with no URL, so the app pops its own back-stack (spec DSL.md
   * §4.5). Null/absent when the slot is `Custom` chrome or at depth 1.
   */
  onNavigateBack?: () => void;
  /** Optional design-token sink (defaults to document-root CSS variables). */
  tokenSink?: DesignTokenSink;
}

/** Apply every opcode in a batch to the DOM (TREE structure + STYLE/META deltas). */
export function applyBatch(batch: Batch, renderer: DomRenderer): void {
  for (const op of batch.opcodes) {
    switch (op.category) {
      case CAT_TREE:
        applyTree(op, renderer);
        break;
      case CAT_STYLE:
        applyStyle(op, batch.strings, renderer);
        break;
      case CAT_META:
        applyMeta(op, renderer);
        break;
      default:
        break;
    }
  }
}

function applyMeta(op: Opcode, r: DomRenderer): void {
  switch (op.command) {
    case CMD_RESET: {
      for (const el of Array.from(r.byId.values())) {
        if (el.parentNode) {
          el.parentNode.removeChild(el);
        }
      }
      r.byId.clear();
      break;
    }
    case CMD_ENVIRONMENT:
    default:
      break;
  }
}

/** The node actually inserted into a parent's container: ZStack children are
 *  wrapped in `<div style="position:absolute;inset:0">` (mirrors the Rust SSR
 *  renderer's per-child wrapper), everything else inserts directly. */
function placedChild(parent: Node, child: Node): Node {
  if (componentByNode.get(parent) === COMPONENT_ZSTACK && child instanceof HTMLElement) {
    // Set via the style attribute so `inset:0` survives verbatim (the CSSOM
    // drops the property in some engines); mirrors the Rust SSR wrapper exactly.
    const wrapper = document.createElement("div");
    wrapper.setAttribute("style", "position:absolute;inset:0");
    wrapper.appendChild(child);
    return wrapper;
  }
  return child;
}

/** Materialize a PICKER's child TEXT node as a native `<option>` (the Rust SSR
 *  renderer emits `<option data-pathland-id="{child}" value="{index}">` per
 *  child). The option keeps the child's id so its STYLE deltas resolve to it. */
function pickerOption(child: HTMLElement): HTMLElement {
  const opt = document.createElement("option");
  opt.textContent = child.textContent ?? "";
  const id = child.getAttribute("data-pathland-id");
  if (id) {
    opt.setAttribute("data-pathland-id", id);
  }
  return opt;
}

/** Keep a PICKER's option `value` attributes aligned with their index (the SSR
 *  renderer's `<option value="{i}">` scheme). */
function renumberPickerOptions(container: Node): void {
  if (!(container instanceof HTMLSelectElement)) {
    return;
  }
  Array.from(container.options).forEach((o, i) => {
    o.value = String(i);
  });
}

function applyTree(op: Opcode, r: DomRenderer): void {
  switch (op.command) {
    case CMD_CREATE_NODE: {
      // Hydration-aware: an id already present in the registry is the SSR-hydrated
      // element — reuse it (a resync/full snapshot replays CREATE for every node
      // without clobbering the visible DOM). Only create a fresh shell when absent.
      let el = r.byId.get(op.a);
      if (!el) {
        el = createElement(op.b);
        if (el.nodeType === Node.ELEMENT_NODE) {
          (el as HTMLElement).setAttribute("data-pathland-id", String(op.a));
        }
        r.byId.set(op.a, el);
      }
      if (el.nodeType === Node.ELEMENT_NODE) {
        componentByNode.set(el, op.b);
      }
      break;
    }
    case CMD_DELETE_NODE: {
      const el = r.byId.get(op.a);
      if (el && el.parentNode) {
        el.parentNode.removeChild(el);
      }
      r.byId.delete(op.a);
      break;
    }
    case CMD_INSERT_CHILD: {
      const parent = r.byId.get(op.a);
      const child = r.byId.get(op.b);
      if (parent && child) {
        const container = childrenContainer(parent);
        // Hydration/idempotent-replay guard: skip when the child is already there
        // (the SSR DOM already holds the initial tree; a resync replays it).
        if (container && !container.contains(child)) {
          let placed = placedChild(parent, child);
          if (componentByNode.get(parent) === COMPONENT_PICKER && child instanceof HTMLElement) {
            // Picker children are option labels → materialize native `<option>`s.
            placed = pickerOption(child);
            r.byId.set(op.b, placed);
            componentByNode.set(placed, COMPONENT_TEXT);
          }
          insertAt(container, placed, op.c);
          if (componentByNode.get(parent) === COMPONENT_PICKER) {
            renumberPickerOptions(container);
          }
          maybeAnimateInsert(parent, placed);
        }
      }
      break;
    }
    case CMD_REMOVE_CHILD: {
      const child = r.byId.get(op.b);
      if (child && child.parentNode) {
        child.parentNode.removeChild(child);
      }
      break;
    }
    case CMD_MOVE_CHILD: {
      const child = r.byId.get(op.b);
      if (!child) {
        break;
      }
      const parent = r.byId.get(op.a);
      if (parent) {
        const container = childrenContainer(parent);
        if (container) {
          // Detach the child (and its now-empty ZStack wrapper, if any) so the
          // wrapper-count stays in sync with the Rust SSR structure.
          const oldParent = child.parentNode;
          child.parentNode?.removeChild(child);
          if (
            oldParent instanceof HTMLElement &&
            oldParent !== container &&
            oldParent.childElementCount === 0 &&
            oldParent.style.position === "absolute"
          ) {
            oldParent.remove();
          }
          let placed = placedChild(parent, child);
          if (componentByNode.get(parent) === COMPONENT_PICKER && child instanceof HTMLElement) {
            placed = pickerOption(child);
            r.byId.set(op.b, placed);
            componentByNode.set(placed, COMPONENT_TEXT);
          }
          insertAt(container, placed, op.c);
          if (componentByNode.get(parent) === COMPONENT_PICKER) {
            renumberPickerOptions(container);
          }
        }
      }
      break;
    }
    default:
      break;
  }
}

function insertAt(container: Node, child: Node, index: number): void {
  const visible = Array.from(container.childNodes).filter(
    (n) =>
      (n.nodeType === Node.ELEMENT_NODE || n.nodeType === Node.COMMENT_NODE) &&
      !(n instanceof HTMLElement && n.classList.contains(NAV_BACK_CLASS)),
  );
  const target = visible[index];
  if (target) {
    container.insertBefore(child, target);
  } else {
    container.appendChild(child);
  }
}

// --- renderer-provided navigation chrome (spec DSL.md §4.5) ---
// A `PlatformDefault` nav slot at depth > 1 gets a default back button drawn by
// the DOM renderer (the web has no native navigation container). The button is
// a tracked child of the slot that the reconcile ignores (see `insertAt`), so
// TREE deltas never displace it. `Custom` chrome slots never get one.

/** The injected default back button's class (excluded from child indexing). */
export const NAV_BACK_CLASS = "pathland-nav-back";

/** Whether an element is a nav slot (carries a `data-pathland-route`). */
function isNavSlot(el: HTMLElement): boolean {
  return el.hasAttribute("data-pathland-route");
}

/** The slot's chrome mode: `true` when the developer owns all nav UI. */
function isCustomChrome(el: HTMLElement): boolean {
  return el.getAttribute("data-pathland-nav-chrome") === "custom";
}

/** The slot's current depth (defaults to 1 = root destination). */
function slotDepth(el: HTMLElement): number {
  return Math.max(1, Number(el.getAttribute("data-pathland-depth") ?? "1") || 1);
}

/** The injected back button inside a slot, if present. */
function injectedBackButton(el: HTMLElement): HTMLButtonElement | null {
  return el.querySelector<HTMLButtonElement>(`.${NAV_BACK_CLASS}`);
}

/**
 * Reconcile the renderer's default back button for a nav slot: shown for a
 * `PlatformDefault` slot at depth > 1, removed for `Custom` chrome or depth 1.
 * Called from `SET_PROPERTY` (depth/chrome changes) and once at hydrate.
 */
export function updateNavBackButton(el: HTMLElement, r: DomRenderer): void {
  if (!isNavSlot(el) || isCustomChrome(el) || slotDepth(el) <= 1) {
    injectedBackButton(el)?.remove();
    return;
  }
  let back = injectedBackButton(el);
  if (!back) {
    back = document.createElement("button");
    back.type = "button";
    back.className = NAV_BACK_CLASS;
    back.setAttribute("aria-label", "Back");
    back.textContent = "‹ Back";
    back.addEventListener("click", () => r.onNavigateBack?.());
    el.insertBefore(back, el.firstChild); // above the destination
  }
}

/** Reconcile the default back button for every nav slot in the tree (hydrate). */
export function updateNavBackButtons(r: DomRenderer): void {
  for (const node of r.byId.values()) {
    if (node instanceof HTMLElement && isNavSlot(node)) {
      updateNavBackButton(node, r);
    }
  }
}

// --- swap transitions (spec DSL.md §4.5 / MODIFIERS.md TRANSITION) ---
// When a child is inserted into a slot carrying a `data-pathland-transition` hint,
// the DOM client animates the new subtree in (fade/slide/scale). This is a pure
// renderer-side animation of its own output cache — never app state.

const TRANSITION_KEYFRAMES: Record<string, string> = {
  platform: "@keyframes pl-platform { from { opacity: 0; } to { opacity: 1; } }",
  fade: "@keyframes pl-fade { from { opacity: 0; } to { opacity: 1; } }",
  slide:
    "@keyframes pl-slide { from { opacity: 0; transform: translateX(16px); } to { opacity: 1; transform: none; } }",
  scale:
    "@keyframes pl-scale { from { opacity: 0; transform: scale(0.96); } to { opacity: 1; transform: none; } }",
};

let transitionsInjected = false;

function ensureTransitionStyles(): void {
  if (transitionsInjected || typeof document === "undefined") {
    return;
  }
  transitionsInjected = true;
  const style = document.createElement("style");
  style.setAttribute("data-pathland-transitions", "");
  style.textContent = Object.values(TRANSITION_KEYFRAMES).join("\n");
  document.head.appendChild(style);
}

function maybeAnimateInsert(parent: Node, child: Node): void {
  if (!(parent instanceof HTMLElement) || !(child instanceof HTMLElement)) {
    return;
  }
  const name = parent.getAttribute("data-pathland-transition");
  if (!name) {
    return;
  }
  ensureTransitionStyles();
  const key = TRANSITION_KEYFRAMES[name] ? name : "platform";
  child.style.animation = `pl-${key} 180ms ease-out`;
  child.addEventListener("animationend", () => {
    child.style.animation = "";
  }, { once: true });
}

/** Resolve an element's role shell kind: from the component when known (fresh
 *  nodes), else from its tag (SSR-hydrated nodes have no component). */
function shellKind(el: HTMLElement): "generic" | "native" | "other" {
  const comp = componentByNode.get(el);
  if (comp !== undefined) {
    if (GENERIC_COMPONENTS.includes(comp)) {
      return "generic";
    }
    if (NATIVE_ROLE_COMPONENTS.includes(comp)) {
      return "native";
    }
    return "other";
  }
  const t = el.tagName.toLowerCase();
  if (t === "div" || t === "span") {
    return el.classList.contains("pathland-menu") || el.classList.contains("pathland-stepper")
      ? "other"
      : "generic";
  }
  if (
    t === "button" ||
    t === "input" ||
    t === "label" ||
    t === "select" ||
    t === "textarea" ||
    t === "progress" ||
    t === "img"
  ) {
    return "native";
  }
  return "other";
}

/** Replace an element with one of a different tag (a semantic role retag),
 *  preserving attributes, children, and the registry entry. */
function morphRole(el: HTMLElement, tag: string, r: DomRenderer): HTMLElement {
  const fresh = document.createElement(tag);
  for (const attr of Array.from(el.attributes)) {
    fresh.setAttribute(attr.name, attr.value);
  }
  while (el.firstChild) {
    fresh.appendChild(el.firstChild);
  }
  if (el.parentNode) {
    el.parentNode.replaceChild(fresh, el);
  }
  const id = Number(el.getAttribute("data-pathland-id"));
  if (id) {
    r.byId.set(id, fresh);
  }
  const comp = componentByNode.get(el);
  if (comp !== undefined) {
    componentByNode.set(fresh, comp);
  }
  const role = roleByNode.get(el);
  if (role !== undefined) {
    roleByNode.set(fresh, role);
  }
  const style = textStyleByNode.get(el);
  if (style !== undefined) {
    textStyleByNode.set(fresh, style);
  }
  return fresh;
}

/** Resolve and apply the semantic tag + ARIA role for an element from its
 *  current `ROLE` / `TEXT_STYLE` state (a heading `TEXT_STYLE` always wins).
 *  Retags a generic shell in place when the effective tag differs. */
function applySemantic(el: HTMLElement, r: DomRenderer): void {
  const kind = shellKind(el);
  const role = roleByNode.get(el) ?? 0;
  const style = textStyleByNode.get(el);
  const tag = textTag(kind, role, style ?? null);
  let current = el;
  if (tag && current.tagName.toLowerCase() !== tag) {
    current = morphRole(current, tag, r);
  }
  const aria = ariaRole(kind, role);
  if (aria) {
    current.setAttribute("role", aria);
  } else {
    current.removeAttribute("role");
  }
}

function applyStyle(op: Opcode, strings: Uint8Array, r: DomRenderer): void {
  if (op.command === CMD_SET_DESIGN_TOKEN) {
    applyDesignToken(op, strings, r.tokenSink ?? createTokenSink());
    return;
  }
  const node = r.byId.get(op.a);
  if (!node || node.nodeType !== Node.ELEMENT_NODE) {
    return;
  }
  const el = node as HTMLElement;
  switch (op.command) {
    case CMD_SET_TEXT:
      setNodeText(el, readString(strings, op.b));
      break;
    case CMD_SET_DATE: {
      const input = el.matches("input[type=date],input[type=time],input[type=datetime-local]")
        ? (el as HTMLInputElement)
        : el.querySelector<HTMLInputElement>("input[type=date],input[type=time],input[type=datetime-local]");
      if (input) {
        if (input.type === "time") {
          input.value = millisToTime(op.c);
        } else if (input.type === "datetime-local") {
          const date = daysToIso(op.b);
          const time = millisToTime(op.c);
          input.value = date ? `${date}T${time}` : time;
        } else {
          input.value = daysToIso(op.b);
        }
      }
      break;
    }
    case CMD_SET_PROPERTY: {
      const propId = op.b & 0xffff;
      const valueType = (op.b >>> 16) & 0xff;
      if (valueType === VAL_STRING) {
        const text = readString(strings, op.c);
        if (propId === PROP_ROUTE) {
          el.setAttribute("data-pathland-route", text);
          r.onRoute?.(text); // host mirrors the URL (history.pushState)
        } else {
          applyStringProperty(el, propId, text);
        }
      } else if (valueType === VAL_DESIGN_TOKEN) {
        applyTokenRefProperty(el, propId, readString(strings, op.c));
      } else if (componentByNode.get(el) === COMPONENT_PROGRESS_VIEW
              && (propId === PROP_IS_INDETERMINATE || propId === PROP_PROGRESS)) {
        applyProgress(el, r, propId, valueType, op.c);
      } else if (propId === PROP_ROLE) {
        // Semantic role → native element where one exists (generated role-spec):
        // a generic shell is retagged to its semantic element; the ARIA `role`
        // attribute is set only when the element does not already convey it.
        roleByNode.set(el, Math.round(f32FromBits(op.c)) & 0xff);
        applySemantic(el, r);
      } else if (propId === PROP_TEXT_STYLE) {
        // A heading `TEXT_STYLE` (LargeTitle…Headline) makes a TEXT a heading
        // (`<h1>`–`<h5>`) — always, even without `ROLE_HEADER`; raw font
        // modifiers never imply a heading. Absence is "no style" (the enum has
        // no NONE — LARGE_TITLE is code 0, a real heading style).
        textStyleByNode.set(el, Math.round(f32FromBits(op.c)) & 0xff);
        applySemantic(el, r);
      } else if (propId === PROP_NAV_DEPTH) {
        // Back-stack depth on a nav slot → the renderer's default back button.
        el.setAttribute("data-pathland-depth", String(op.c));
        updateNavBackButton(el, r);
      } else if (propId === PROP_NAV_CHROME) {
        // Chrome mode: PlatformDefault=0 / Custom=1 (F32 enum code).
        const custom = Math.round(f32FromBits(op.c)) === 1;
        if (custom) {
          el.setAttribute("data-pathland-nav-chrome", "custom");
        } else {
          el.removeAttribute("data-pathland-nav-chrome");
        }
        updateNavBackButton(el, r);
      } else {
        applyNumericProperty(el, propId, valueType, op.c);
      }
      break;
    }
    default:
      break;
  }
}

/** Set a node's text, honoring text fields/editors and label spans (SSR structure). */
export function setNodeText(el: HTMLElement, text: string): void {
  const input = el.querySelector("input[type=text],input[type=password]");
  if (input instanceof HTMLInputElement) {
    input.value = text;
    return;
  }
  const textarea = el.querySelector("textarea");
  if (textarea instanceof HTMLTextAreaElement) {
    textarea.value = text;
    return;
  }
  const trigger = el.querySelector(".pathland-menu-trigger");
  if (trigger) {
    trigger.textContent = text;
    return;
  }
  const span = el.querySelector(".pathland-text");
  if (span) {
    span.textContent = text;
    return;
  }
  el.textContent = text;
}

function applyStringProperty(el: HTMLElement, propId: number, text: string): void {
  switch (propId) {
    case PROP_TEXT:
    case PROP_LABEL: {
      const span = el.querySelector(".pathland-label");
      if (span) {
        span.textContent = text;
      } else {
        setNodeText(el, text);
      }
      break;
    }
    case PROP_PROMPT: {
      const input = el.querySelector("input[type=text]");
      if (input instanceof HTMLInputElement) {
        input.placeholder = text;
      }
      break;
    }
    case PROP_IMAGE_SOURCE: {
      const img = el.matches("img") ? el : el.querySelector("img");
      if (img instanceof HTMLImageElement) {
        img.src = text;
      }
      break;
    }
    case PROP_FONT_FAMILY: {
      el.style.fontFamily = text;
      break;
    }
    default:
      break;
  }
}

function applyNumericProperty(el: HTMLElement, propId: number, valueType: number, bits: number): void {
  switch (propId) {
    case PROP_SELECTED: {
      const input = el.querySelector<HTMLInputElement>("input[type=checkbox]");
      if (input) {
        const on = (valueType === 0x01 ? bits & 0xff : bits) !== 0;
        input.checked = on;
        // Button-style toggles are rendered with `role=checkbox` + `aria-pressed`
        // (the Rust SSR renderer's TOGGLE_STYLE=Button); switch/checkbox styles
        // carry only the native `checked` state.
        if (input.getAttribute("role") === "checkbox") {
          input.setAttribute("aria-pressed", on ? "true" : "false");
        }
      }
      break;
    }
    case PROP_VALUE: {
      const range = el.querySelector<HTMLInputElement>("input[type=range]");
      if (range) {
        range.value = String(f32FromBits(bits));
      }
      const stepText = el.querySelector(".pathland-stepper span");
      if (stepText) {
        stepText.textContent = String(Math.round(f32FromBits(bits) * 100) / 100);
      }
      const gauge = el.matches(".pathland-gauge")
        ? el
        : el.querySelector<HTMLElement>(".pathland-gauge");
      if (gauge) {
        const max = Number(gauge.dataset.max ?? 1);
        const min = Number(gauge.dataset.min ?? 0);
        const span = max - min;
        const pct = span <= 0 ? 0 : ((f32FromBits(bits) - min) / span) * 100;
        const bar = gauge.firstElementChild;
        if (bar instanceof HTMLElement) {
          bar.style.width = pct + "%";
        }
      }
      break;
    }
    case PROP_SELECTION: {
      const select = el.matches("select")
        ? (el as HTMLSelectElement)
        : el.querySelector<HTMLSelectElement>("select");
      if (select) {
        // Index-based, matching the SSR `<option value="{index}">` scheme.
        select.selectedIndex = bits;
      }
      break;
    }
    case PROP_COLOR_VALUE: {
      const input = el.matches("input[type=color]")
        ? el
        : el.querySelector<HTMLInputElement>("input[type=color]");
      if (input instanceof HTMLInputElement) {
        input.value = argbToHex(bits);
      }
      break;
    }
    case PROP_BINDING_ID: {
      el.dataset.bindingId = String(bits >>> 0);
      break;
    }
    case PROP_COLOR: {
      // A COLOR / SHAPE node's COLOR property is its fill: it renders as a
      // background (the generic handler below sets the text color, which the
      // Rust SSR renderer also emits alongside the fill).
      const comp = componentByNode.get(el);
      if (comp === COMPONENT_COLOR || comp === COMPONENT_SHAPE) {
        el.style.backgroundColor = argbToRgba(bits);
      }
      applyProperty(el, propId, valueType, bits);
      break;
    }
    case PROP_ENABLED:
      applyEnabled(el, bits);
      break;
    case PROP_WIDTH: {
      // A GRID's WIDTH property is the cell-axis count, mirrored into
      // `grid-template-columns` (the Rust SSR renderer's `grid_style`); the
      // width is still applied literally by the generic handler below.
      const comp = componentByNode.get(el);
      if (comp === COMPONENT_GRID || comp === COMPONENT_LAZY_VGRID || comp === COMPONENT_LAZY_HGRID) {
        const n = f32FromBits(bits);
        el.style.gridTemplateColumns = n > 0 ? `repeat(${Math.round(n)},1fr)` : "";
      }
      applyProperty(el, propId, valueType, bits);
      break;
    }
    default:
      applyProperty(el, propId, valueType, bits);
      break;
  }
}

/**
 * A ProgressView's indicator properties: morphs the element between the
 * determinate `<progress>` and the indeterminate `pathland-spinner` div (the
 * Rust renderer's SSR shapes) and applies the determinate value. Mirrors the
 * Rust indeterminate rule: `IS_INDETERMINATE != 0 || PROGRESS < 0`.
 */
function applyProgress(el: HTMLElement, r: DomRenderer, propId: number, valueType: number, bits: number): void {
  const on = valueType === VAL_U8 ? bits & 0xff : bits;
  const indeterminate = propId === PROP_IS_INDETERMINATE ? on !== 0 : f32FromBits(bits) < 0;
  const el2 = morphProgress(el, r, indeterminate);
  if (propId === PROP_PROGRESS && el2 instanceof HTMLProgressElement) {
    const value = Math.min(1, Math.max(0, f32FromBits(bits)));
    el2.value = value;
    el2.max = 1;
  }
}

/** Replace a ProgressView element between its two shapes, preserving attributes and the byId entry. */
function morphProgress(el: HTMLElement, r: DomRenderer, wantSpinner: boolean): HTMLElement {
  const isSpinner = el.classList.contains("pathland-spinner");
  if (wantSpinner === isSpinner) {
    return el;
  }
  const fresh = wantSpinner
    ? (() => {
        const s = document.createElement("div");
        s.className = "pathland-spinner";
        return s;
      })()
    : (() => {
        const p = document.createElement("progress");
        p.max = 1;
        return p;
      })();
  for (const attr of Array.from(el.attributes)) {
    // A spinner is a plain div — it carries no `max`/`value` (the Rust SSR
    // renderer's `<div class="pathland-spinner">`).
    if (wantSpinner && (attr.name === "max" || attr.name === "value")) {
      continue;
    }
    fresh.setAttribute(attr.name, attr.value);
  }
  if (el.parentNode) {
    el.parentNode.replaceChild(fresh, el);
  }
  const id = Number(el.getAttribute("data-pathland-id"));
  if (id) {
    r.byId.set(id, fresh);
  }
  componentByNode.set(fresh, COMPONENT_PROGRESS_VIEW);
  return fresh;
}

