package com.pathland.demo.sidebar;

import com.pathland.view.*;
import com.pathland.view.router.Navigation;
import com.pathland.view.router.Router;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;

public class Sidebar implements View {
    // Environment.value returns a lazy signal when the key isn't bound yet — this
    // field is initialized before SplitNavDemo's `.environment(ROUTER, router)` scope
    // is pushed, so it resolves on .get() inside body(), at render time.
    private final Signal<Router> router = Environment.value(Navigation.ROUTER);
    private static final Color SIDEBAR_BG = Color.rgb(0xF2, 0xF3, 0xF7);
    private static final Color SIDEBAR_BORDER = Color.rgb(0xDD, 0xE0, 0xE8);
    private static final Color ACTIVE_BG = Color.rgb(0xDC, 0xE4, 0xFF);
    private static final Color ACTIVE_FG = Color.rgb(0x1A, 0x3A, 0x8C);

    @Override
    public View body() {
        // The router signal resolves here, inside SplitNavDemo's pushed
        // .environment(Navigation.ROUTER, router) scope.
        return VStack.of(Alignment.FILL, 8,
                        Text.of("Pathland").modifiers(
                                FontSize.of(18), FontWeightMod.of(FontWeight.BOLD)),
                        menuRow("/home", "Home", "icons/home.svg"),
                        menuRow("/kitchen", "Kitchen sink", "icons/kitchen.svg"),
                        menuRow("/settings", "Settings", "icons/settings.svg"),
                        Spacer.of()
                ).modifiers(Padding.of(16))
                // Fixed-width sidebar with no height hint: as a flex child of the split
                // HStack it stretches to the row's full height (align-items: stretch).
                // Alignment is omitted so the stack's own FILL child-alignment (stretch
                // the menu rows) is preserved.
                .modifier(FrameMod.of(200f))
                .modifier(Background.of(SIDEBAR_BG))
                .modifier(Border.of(SIDEBAR_BORDER, 1f))
                // The sidebar is the app's primary navigation region → a `<nav>` landmark.
                .modifier(AccessibilityRole.of(Roles.NAVIGATION))
                // Custom-looking buttons: real `Button`s styled with a `ButtonStyle`
                // (control semantics are intrinsic to the component, not a `ROLE`).
                .modifier(ButtonStyleMod.of(PlainButtonStyle.INSTANCE));
    }

    /** A sidebar menu row (a {@link Label}): navigates the router (direct selection — no
     *  back-stack growth). The sidebar sits outside the {@code NavigationContainer} (it is
     *  the developer's own nav chrome), so it captures the router explicitly — the
     *  nearest-enclosing-router mechanism (spec DSL.md §4.5) resolves intents for
     *  components *inside* a container. */
    private View menuRow(String path, String label, String icon) {
        // Reactive active-item highlight via Navigation.isActive: a computed signal from
        // the route signal, so a selection re-emits only this row's background/color.
        var router = this.router.get();
        Signal<Boolean> active = Navigation.isActive(router, path);
        Signal<Color> bg = Signals.computed(() -> active.get() ? ACTIVE_BG : Color.CLEAR);
        Signal<Color> fg = Signals.computed(() -> active.get() ? ACTIVE_FG : Color.BLACK);

        return Button.of(
                Label.of(label, icon).modifiers(Background.of(bg), ForegroundStyle.of(fg)),
                () -> router.navigate(path)
        );
        //return Button.of(label, () -> router.navigate(path))
        //        .modifiers(Background.of(bg), ForegroundStyle.of(fg));
    }
}

package com.pathland.view;

import com.pathland.view.signal.Signal;

import java.util.ArrayList;
import java.util.List;

/**
 * A text title with an optional icon (SwiftUI {@code Label}), composed from the
 * existing primitives — an {@link HStack} of an {@link Image} and a {@link Text} —
 * so it is reusable anywhere a view is (buttons, menus, pickers, sidebar rows).
 *
 * <p>The {@link LabelStyle} scoped in the environment decides which parts render
 * (spec DSL.md §5.5): the default {@code TITLE_AND_ICON} shows both,
 * {@code TITLE_ONLY} drops the icon, {@code ICON_ONLY} drops the title. The title
 * is <em>always</em> the label's accessibility label, even when only the icon is
 * shown — so an icon-only label stays announced by screen readers. A blank title
 * or icon is suppressed.
 *
 * <p>The title/icon may be static or bound to a signal; bound text/source/label
 * re-emit only that node's delta when the signal changes. Whether a part is
 * <em>present</em> is decided at mount (label style is a mount-time scope); issue
 * #88 tracks re-shaping a subtree when a signal read during render changes.
 */
public final class Label implements View {

    private final String title;
    private final Signal<String> titleSignal;
    private final String icon;
    private final Signal<String> iconSignal;

    private Label(String title, Signal<String> titleSignal, String icon, Signal<String> iconSignal) {
        this.title = title;
        this.titleSignal = titleSignal;
        this.icon = icon;
        this.iconSignal = iconSignal;
    }

    /** A title-only label (no icon). */
    public static Label of(String title) {
        return new Label(title, null, null, null);
    }

    /** A label with a title and an icon. */
    public static Label of(String title, String icon) {
        return new Label(title, null, icon, null);
    }

    /** A title-only label whose title is bound to a reactive signal. */
    public static Label of(Signal<String> title) {
        return new Label(null, title, null, null);
    }

    /** A label with a reactive title and a static icon. */
    public static Label of(Signal<String> title, String icon) {
        return new Label(null, title, icon, null);
    }

    /** A label with a static title and a reactive icon. */
    public static Label of(String title, Signal<String> icon) {
        return new Label(title, null, null, icon);
    }

    /** A label whose title and icon are both bound to reactive signals. */
    public static Label of(Signal<String> title, Signal<String> icon) {
        return new Label(null, title, null, icon);
    }

    @Override
    public View body() {
        LabelStyle style = Environment.value(Environment.LABEL_STYLE).get();
        if (style == null) {
            style = LabelStyle.TITLE_AND_ICON;
        }
        String title = value(this.title, this.titleSignal);
        String icon = value(this.icon, this.iconSignal);

        List<View> children = new ArrayList<>(2);
        if (nonBlank(icon) && style.showsIcon()) {
            children.add(iconSignal != null ? Image.of(iconSignal) : Image.of(icon));
        }
        if (nonBlank(title) && style.showsTitle()) {
            View text = titleSignal != null ? Text.of(titleSignal) : Text.of(title);
            children.add(text.modifier(LineLimit.of(1)));
        }

        View stack = HStack.of(Alignment.CENTER, 2f, children);
        if (nonBlank(title)) {
            stack = stack.modifier(titleSignal != null
                    ? AccessibilityLabel.of(titleSignal)
                    : AccessibilityLabel.of(title));
        }
        return stack;
    }

    /** The current value: a static one, or the signal's current value. */
    private static String value(String staticValue, Signal<String> signal) {
        return signal != null ? signal.get() : staticValue;
    }

    private static boolean nonBlank(String value) {
        return value != null && !value.isBlank();
    }
}

